    "ja": "クラレッタ専用：数値はいずれもステータス画面（戦闘外）の値です。会心率129%は Game8 の「戦闘中に自身で71%上げるため、キャラのステータスは129%にする」、128.9%は GameWith の Lv.60 開幕ステータス。戦闘中の上乗せ（最大199.9%）は加算しません。防御力は GameWith の開幕値2,451を厳選、棘まとう薔薇4セット効果が会心率を+16%/+8%する開幕防御力1,800/1,000を目標・妥協に採りました。会心ダメージは GameWith が98%を挙げる一方、Game8 は「会心時は会心ダメージではなく暴傷ダメージが適用されるため盛る意味がない」としており、出典が割れているため比較対象に入れていません。心象映画・編成・音動機の効果も公開プロフィールへ加算しません。",
